    /**
     * Parses and validates a PSBT against the immutable caller intent without
     * producing any signatures.
     *
     * # Errors
     *
     * Returns `InvalidPsbt`, `InvalidNetwork`, or `PolicyRejected` on any
     * malformed or unapproved transaction property.
     */
    @Throws(SignerException::class)override fun `validatePsbt`(`psbtBase64`: kotlin.String, `intent`: SigningIntent): ValidationReport {
            return FfiConverterTypeValidationReport.lift(
