/**
 * Stable failure categories crossing the native-language boundary.
 *
 * Messages are deliberately safe to surface. They never include key material,
 * raw PSBTs, invoices, or backend payloads.
 */
sealed class SignerException: kotlin.Exception() {
    
    class InvalidArgument(
        
        val `reason`: kotlin.String
        ) : SignerException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    class InvalidMnemonic(
        ) : SignerException() {
        override val message
            get() = ""
    }
    
    class InvalidSeed(
        ) : SignerException() {
        override val message
            get() = ""
    }
    
    class EntropyUnavailable(
        ) : SignerException() {
        override val message
            get() = ""
    }
    
    class InvalidNetwork(
        
        val `reason`: kotlin.String
        ) : SignerException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    class InvalidPsbt(
        
        val `reason`: kotlin.String
        ) : SignerException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    class PolicyRejected(
        
        val `reason`: kotlin.String
        ) : SignerException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    class KeyDerivation(
        ) : SignerException() {
        override val message
            get() = ""
    }
    
    class SigningFailed(
        ) : SignerException() {
        override val message
            get() = ""
    }
    
    class SignatureVerification(
        ) : SignerException() {
        override val message
            get() = ""
    }
    
    class InvalidRgbInvoice(
        
        val `reason`: kotlin.String
        ) : SignerException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<SignerException> {
        override fun lift(error_buf: RustBuffer.ByValue): SignerException = FfiConverterTypeSignerError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeSignerError : FfiConverterRustBuffer<SignerException> {
    override fun read(buf: ByteBuffer): SignerException {
        

        return when(buf.getInt()) {
            1 -> SignerException.InvalidArgument(
                FfiConverterString.read(buf),
                )
            2 -> SignerException.InvalidMnemonic()
            3 -> SignerException.InvalidSeed()
            4 -> SignerException.EntropyUnavailable()
            5 -> SignerException.InvalidNetwork(
                FfiConverterString.read(buf),
                )
            6 -> SignerException.InvalidPsbt(
                FfiConverterString.read(buf),
                )
            7 -> SignerException.PolicyRejected(
                FfiConverterString.read(buf),
                )
            8 -> SignerException.KeyDerivation()
            9 -> SignerException.SigningFailed()
            10 -> SignerException.SignatureVerification()
            11 -> SignerException.InvalidRgbInvoice(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: SignerException): ULong {
        return when(value) {
            is SignerException.InvalidArgument -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is SignerException.InvalidMnemonic -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is SignerException.InvalidSeed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is SignerException.EntropyUnavailable -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is SignerException.InvalidNetwork -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is SignerException.InvalidPsbt -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is SignerException.PolicyRejected -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is SignerException.KeyDerivation -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is SignerException.SigningFailed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is SignerException.SignatureVerification -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is SignerException.InvalidRgbInvoice -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
    }

    override fun write(value: SignerException, buf: ByteBuffer) {
        when(value) {
            is SignerException.InvalidArgument -> {
                buf.putInt(1)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is SignerException.InvalidMnemonic -> {
                buf.putInt(2)
                Unit
            }
            is SignerException.InvalidSeed -> {
                buf.putInt(3)
                Unit
            }
            is SignerException.EntropyUnavailable -> {
                buf.putInt(4)
                Unit
            }
            is SignerException.InvalidNetwork -> {
                buf.putInt(5)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is SignerException.InvalidPsbt -> {
                buf.putInt(6)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is SignerException.PolicyRejected -> {
                buf.putInt(7)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is SignerException.KeyDerivation -> {
                buf.putInt(8)
                Unit
            }
            is SignerException.SigningFailed -> {
                buf.putInt(9)
                Unit
            }
            is SignerException.SignatureVerification -> {
                buf.putInt(10)
                Unit
            }
            is SignerException.InvalidRgbInvoice -> {
                buf.putInt(11)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




